import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ source for custom min reduction (dim=1) and fused double tanh
custom_kernels_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void min_along_dim1_kernel(const float* input, float* output,
                                      int N, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = N * H * W;
    if (idx < total_size) {
        int w = idx % W;
        int h = (idx / W) % H;
        int n = idx / (H * W);

        float min_val = input[n*C*H*W + 0*H*W + h*W + w];
        for (int c = 1; c < C; c++) {
            float val = input[n*C*H*W + c*H*W + h*W + w];
            if (val < min_val) {
                min_val = val;
            }
        }
        output[n*H*W + h*W + w] = min_val; // keepdim => shape [N,1,H,W]
    }
}

torch::Tensor min_along_dim1_cuda(torch::Tensor input) {
    // input shape: [N, C, H, W]
    auto sizes = input.sizes();
    int N = sizes[0];
    int C = sizes[1];
    int H = sizes[2];
    int W = sizes[3];

    // Allocate output shape: [N, 1, H, W]
    auto out_sizes = std::vector<int64_t>{N, 1, H, W};
    auto output = torch::zeros(out_sizes, input.options());

    int total_size = N * H * W;
    int block_size = 256;
    int num_blocks = (total_size + block_size - 1) / block_size;

    min_along_dim1_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(),
                                                      output.data_ptr<float>(),
                                                      N, C, H, W);
    return output;
}

__global__ void double_tanh_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = tanhf(input[idx]);
        output[idx] = tanhf(val);
    }
}

torch::Tensor double_tanh_cuda(torch::Tensor input) {
    auto out = torch::zeros_like(input);
    int size = input.numel();
    int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    double_tanh_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(),
                                                   out.data_ptr<float>(),
                                                   size);
    return out;
}
"""

custom_kernels_cpp_source = r"""
torch::Tensor min_along_dim1_cuda(torch::Tensor input);
torch::Tensor double_tanh_cuda(torch::Tensor input);
"""

custom_kernels = load_inline(
    name="custom_kernels",
    cpp_sources=custom_kernels_cpp_source,
    cuda_sources=custom_kernels_source,
    functions=["min_along_dim1_cuda", "double_tanh_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    """
    Optimized model that uses PyTorch conv2d and custom CUDA ops for min reduction and fused double tanh.
    """
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.custom_ops = custom_kernels

    def forward(self, x):
        x = self.conv(x)
        x = self.custom_ops.min_along_dim1_cuda(x)
        x = self.custom_ops.double_tanh_cuda(x)
        return x

